UPDATE auth_device
SET last_used_at = #{usedAt},
    updated_at = #{usedAt}
WHERE device_id = CAST(#{deviceId} AS UUID)
  AND revoked_at IS NULL
  AND expires_at > #{usedAt}

UPDATE auth_device
SET revoked_at = #{revokedAt},
    updated_at = #{revokedAt}
WHERE device_id = CAST(#{deviceId} AS UUID)
  AND user_id = #{userId}
  AND revoked_at IS NULL
